  "anomalies": [
    {
      "category": "extra_component",
      "components": ["PR5", "H2"],
      "pins": ["PR5.VCC", "PR5.SDA", "PR5.SCL", "PR5.GND", "H2.1", "H2.2", "H2.3", "H2.4"],
      "nets": ["+5V", "NET0008", "NET0062", "GND"],
      "observed": "Sheet 1, section 'Water Level Sensor/Switches', shows PR5 LiDAR connected through H2 to +5V, NET0008, NET0062, and GND, i.e. wired onto the main I2C bus.",
      "expected": "The specification states the TF-Luna LiDAR is present in the BOM but not wired: 'its pins are \"free\" and it is marked on_board: no / excluded from the board; it is not wired into any net.' The intended wired water-level sensing is the HC-SR04-style ultrasonic sensor on two GPIOs.",
      "evidence": [
        {"source": "schematic", "quote": "Sheet 1, 'Water Level Sensor/Switches': PR5 LiDAR pins VCC/SDA/SCL/GND connected to +5V, NET0008, NET0062, GND via H2"},
        {"source": "spec", "quote": "TF-Luna LiDAR ... pins are 'free' and it is marked on_board: no / excluded from the board; it is not wired into any net."}
      ],
      "impact": "Adds an unexpected I2C device/load to the main bus and replaces the specified ultrasonic water-level sensing path with a LiDAR interface, so level sensing and bus behavior differ from the intended design.",
      "confidence": 0.8
    },
    {
      "category": "bridged_nets",
      "components": ["U9", "H5", "P13", "R50", "T3"],
      "pins": ["U9.24", "H5.1", "R50.1", "T3.1"],
      "nets": ["NET0088"],
      "observed": "The net label NET0088 appears on U9 pin 24 (OA1, a pH peristaltic-pump coil output) and also on the ATO-valve gate-drive path at R50/T3 base.",
      "expected": "TMC2209 coil outputs should connect only to the pump connector, and ATO_VALVE should be a separate control net driven from the MCU through R50/T3. The specification separates stepper coil outputs from the ATO valve switch.",
      "evidence": [
        {"source": "schematic", "quote": "Sheet 2, 'Ph ↓ Pump': U9 pin 24 OA1 is labeled NET0088 and connects to H5 pin 1"},
        {"source": "schematic", "quote": "Sheet 3, 'ATO Valve': R50 input is labeled NET0088 and connects to T3 base"},
        {"source": "spec", "quote": "each drives a 2-phase coil output (/A_xx+/-, /B_xx+/-) to connectors H7/H8/H9 ... T3 — AON6407 ... drives ATO_VALVE net"}
      ],
      "impact": "The pH pump coil output is shorted into the ATO valve gate-drive circuit, so stepper operation can inadvertently drive the valve and the valve control can load the motor driver, potentially causing incorrect dosing/ATO behavior or driver damage.",
      "confidence": 0.65
    }
  ],
  "summary": "The schematic contains at least one clear deviation: the TF-Luna LiDAR is wired to the main I2C bus even though the specification says it is not wired. It also appears to merge the NET0088 net between a TMC2209 coil output and the ATO valve gate drive, which is a separate connectivity anomaly."
}

